function selectKill(kc){state.cur=kc;ensureMap(kc.raw.world);ensureObjects(kc.raw.world);requestObjectTiles(kc);state.hidden.clear();state.t=kc.tFrom;state.playing=false;state.lastEventRender=-1;$('empty').hidden=true;fitView();renderKillList();renderInfo();renderPlayers();renderEvents(true);updateTransport();showTab('info');}
