function losRow(label,r){if(r===undefined||r===null)return`<tr><td>${label}</td><td class="muted">not computed</td></tr>`;if(r.clear)return`<tr><td>${label}</td><td style="color:${C.good}">clear</td></tr>`;const what=r.terrain?'terrain':(r.player?`player ${esc(r.blocker)}`:esc(r.blocker||'object'));return`<tr><td>${label}</td><td style="color:${C.bad}">blocked by ${what} at ${(r.dist || 0).toFixed(1)} m</td></tr>`;}
