if(k==='impact'){line('rgba(79,195,247,.6)');drawX(g,32,8,3,IMPACT_COLOR[0],1.5);}
if(k==='aiDealt'){g.fillStyle=AI_DEALT_COLOR;g.beginPath();g.arc(18,8,5,0,7);g.fill();}
