if(k==='losClear')line(C.good,[4,3]);if(k==='losBlocked'){line(C.bad,[4,3]);drawX(g,26,8,4,C.bad);}
if(k==='zombie')drawAiMarker(g,18,8,0,MIND_COLOR[3],true,false);if(k==='animal')drawAiMarker(g,18,8,0,ANIMAL_COLOR,true,false);if(k==='vehicle'){g.fillStyle=COLORS[1];g.globalAlpha=0.35;g.fillRect(6,3,24,10);g.globalAlpha=1;g.strokeStyle=COLORS[1];g.lineWidth=2;g.strokeRect(6,3,24,10);g.lineWidth=3.5;g.beginPath();g.moveTo(30,3);g.lineTo(30,13);g.stroke();}
if(k==='vehicleEmpty'){g.fillStyle=EMPTY_VEHICLE.fill;g.fillRect(6,3,24,10);g.strokeStyle=EMPTY_VEHICLE.stroke;g.lineWidth=1.2;g.setLineDash([4,3]);g.strokeRect(6,3,24,10);g.lineWidth=2.5;g.beginPath();g.moveTo(30,3);g.lineTo(30,13);g.stroke();g.setLineDash([]);}
